func:
// Pede ao Supabase só os eventos depois do último já copiado.
// select=*,partidas(...) traz junto os nomes dos times (chave estrangeira).
// Depois de reiniciar o Node-RED o contador volta a 0 e copia tudo de novo:
// não duplica, o InfluxDB sobrescreve pontos com o mesmo horário e tags.
const ultimo = flow.get('ultimoEvento') || 0;
msg.url = env.get('SUPABASE_URL') + '/rest/v1/eventos'
        + '?select=*,partidas(time_a,time_b)'
        + '&id=gt.' + ultimo + '&order=id.asc&limit=500';
msg.headers = {
    apikey: env.get('SUPABASE_KEY'),
    Authorization: 'Bearer ' + env.get('SUPABASE_KEY')
};
return msg;

// Cada linha da tabela eventos vira um ponto do InfluxDB (measurement "evento").
// tags   = o que se usa para filtrar/agrupar (texto curto, poucos valores)
// fields = os números do jogo e os nomes dos times
// Obs.: "time" é palavra reservada no InfluxDB, por isso a tag se chama "equipe".
if (msg.statusCode !== 200 || !Array.isArray(msg.payload)) {
    node.status({ fill: 'red', shape: 'ring', text: 'erro ' + msg.statusCode });
    node.warn(msg.payload);
    return null;
}
if (msg.payload.length === 0) return null;
flow.set('ultimoEvento', msg.payload[msg.payload.length - 1].id);

msg.payload = msg.payload.map(e => ({
    measurement: 'evento',
    tags: {
        placar_id: e.placar_id,
        partida_id: String(e.partida_id ?? 0),
        modo: e.modo,
        tipo: e.tipo,
        equipe: e.time ?? '-'
    },
    fields: {
        placar_a: e.placar_a,
        placar_b: e.placar_b,
        sets_a: e.sets_a,
        sets_b: e.sets_b,
        periodo: e.periodo,
        tempo_jogo_s: e.tempo_jogo_s,
        time_a: e.partidas?.time_a ?? 'A',
        time_b: e.partidas?.time_b ?? 'B'
    },
    timestamp: new Date(e.created_at)
}));

node.status({ fill: 'green', shape: 'dot', text: 'último id ' + flow.get('ultimoEvento') });
return msg;

// Só a última telemetria: serve para saber se o placar está online
// (o ESP manda uma a cada ~60 s; o Grafana mostra OFFLINE se passar de 3 min).
msg.url = env.get('SUPABASE_URL') + '/rest/v1/telemetria?order=id.desc&limit=1';
msg.headers = {
    apikey: env.get('SUPABASE_KEY'),
    Authorization: 'Bearer ' + env.get('SUPABASE_KEY')
};
return msg;

if (msg.statusCode !== 200 || !Array.isArray(msg.payload)) {
    node.status({ fill: 'red', shape: 'ring', text: 'erro ' + msg.statusCode });
    node.warn(msg.payload);
    return null;
}
if (msg.payload.length === 0) return null;

const t = msg.payload[0];
if (t.id === flow.get('ultimaTelemetria')) return null;   // nada novo
flow.set('ultimaTelemetria', t.id);

msg.payload = [{
    measurement: 'telemetria',
    tags: { placar_id: t.placar_id },
    fields: { rssi: t.rssi, heap_livre: t.heap_livre, uptime_s: t.uptime_s },
    timestamp: new Date(t.created_at)
}];
node.status({ fill: 'green', shape: 'dot', text: 'recebida ' + new Date(t.created_at).toLocaleTimeString('pt-BR') });
return msg;
